(29068,12,0,'$n, I\'d recognize that face anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29386,0,'special_surprise SAY_EXEC_RECOG_1'),
(29068,13,0,'$n, I\'d recognize those face tentacles anywhere... What... What have they done to you, $n?',12,0,100,0,0,0,29360,0,'special_surprise SAY_EXEC_RECOG_2'),
