(33507,2,2,'Hurry, Brutusk. I\'m wounded!',12,0,100,0,0,0,0,0,''),
(33507,3,3,'I am... finished....',12,0,100,0,0,0,0,0,''),
(33507,4,4,'To Mor\'shan!!',12,0,100,0,0,0,0,0,''),
(33507,5,5,'Unghh!',12,0,100,0,0,0,0,0,''),
