(38441,0,0,'Little help here!',14,0,100,0,0,0,38767,0,'Ace'),
(38441,1,0,'I never liked that guy. He stole your girlfriend. I say, good riddance!',12,0,100,273,0,0,50108,0,'Ace to Player'),
(38448,0,0,'WHO DARES?!',14,0,100,15,0,15136,38338,0,'Faceless of the Deep to Player'),
(38448,1,0,'Little goblins? I remember when your race was created.',14,0,100,1,0,15139,38346,0,'Faceless of the Deep to Player'),
(38448,2,0,'I care nothing for your threats or these naga. Prepare to be removed from existence.',14,0,100,25,0,15140,38349,0,'Faceless of the Deep to Player'),
(38448,3,0,'Now, young $n, you will die!',14,0,100,0,0,15140,38359,0,'Faceless of the Deep to Player'),
