(56173,0,0,'You have done NOTHING. I will tear your world APART.',14,0,100,0,0,26527,55860,0,'Madness of Deathwing - aggro'),
(56173,1,0,'I AM DEATHWING, THE DESTROYER, THE END OF ALL THINGS, INEVITABLE, INDOMITABLE; I AM THE CATACLYSM!',14,0,100,0,0,26353,55785,0,'Madness of Deathwing - phase 2'),
(56173,2,0,'There is no shelter from my fury.',14,0,100,0,0,26354,55779,0,'Madness of Deathwing - arrow 1'),
(56173,2,1,'Your armor means nothing, your faith even less.',14,0,100,0,0,26355,55780,0,'Madness of Deathwing - arrow 2'),
(56173,2,2,'The sea will swallow your smoldering remains.',14,0,100,0,0,26356,55781,0,'Madness of Deathwing - arrow 3'),
(56173,3,0,'Mutated Corruption begins to impale the Aspect! Stop it!',41,0,100,0,0,0,0,0,'Madness of Deathwing - Impale Aspect'),
