(79521,1,1,'They\'re breaking through. Retreat! We\'ll make our final stand on the stairs!',12,0,100,0,0,0,0,0,''),
(79521,2,2,'Up there! The fleet commander shows himself!',12,0,100,0,0,0,0,0,''),
(79521,3,0,'Hold the barricades! Protect the defense crystal at all costs!',14,0,100,5,0,45673,81623,0,'Yrel to Player'),
