(83587,3,0,'Встретимся там.',12,0,100,396,0,0,96641,0,'Гульда Теневой Клинок to Player'),
(83606,0,0,'А теперь можно зайти?',12,0,100,1,0,0,81695,0,'Люси Расторгуйка to Player'),
