(100497,2,0,'I WILL FLATTEN YOU LIKE SAPLINGS!',14,0,100,0,0,58385,0,0,'Ursoc to Player'),
(100497,3,0,'|TInterface\\Icons\\ability_deathwing_assualtaspects:20|t%s goes into a crazed |cFFFF0000|Hspell:198388|h[Blood Frenzy]|h|r!',41,0,100,0,0,0,0,0,'Ursoc'),
