(100538,0,0,'I\'m going to Dalaran. See you, $n.',12,0,100,1,0,0,103017,0,'Тимоти Джонс to Player'),
(100543,3,0,'Я в долгу не останусь.',12,0,100,0,0,57055,102567,0,'Охотница на демонов to Player'),
(100545,3,0,'Мы добудем ключ!',12,0,100,0,0,57123,102571,0,'Охотник на демонов to Player'),
(100546,0,0,'Leave the mortals alive. We must find the weapons of their so-called \'Storm-God.\'',12,0,100,0,0,0,102527,0,'Лорд Кра\'вос to 0'),
