(100578,6,0,'Riders on our flank! Be ready!',14,0,100,0,0,0,102827,0,'Ревил Кост to Player'),
(100578,7,0,'Надо поднажать. Мы почти у цели.',12,0,100,0,0,0,102830,0,'Ревил Кост to Player'),
(100578,9,0,'Here! The camp is in this clearing. Let us search it.',12,0,100,0,0,0,102831,0,'Ревил Кост to Player'),
(100595,0,0,'Begone, filthy $c! Baelbug find the glaive and keeps it!',12,0,100,0,0,0,106040,0,'Baelbug to Player'),
(100595,1,0,'You no take warglaive!',12,0,100,0,0,0,102723,0,'Baelbug to Player'),
