(110378,1,2,'Фу... воняет.',14,0,100,0,0,0,120815,0,'Драгон Зиморожденный to Player'),
(110398,0,0,'Да, я добыл семя плеточника из-под корней Шаладрассила.',12,0,100,0,0,66745,111956,0,'Наралекс to Player'),
(110398,1,0,'Возьми это семя и посади его в землю прямо здесь.',12,0,100,1,0,66741,111957,0,'Наралекс to Player'),
(110399,0,0,'Ко мне, братья! Пылающий Легион атакует!',12,0,100,0,0,0,116717,0,'Сеста Звездочет to Player'),
(110399,1,0,'Не может быть! Ты вовсе не демон!',12,0,100,0,0,0,116716,0,'Сеста Звездочет to Player'),
