(110401,1,0,'I found peace again.',12,0,100,0,0,0,116719,0,'Т\'рель Лунный Клинок to Player'),
(110428,3,0,'Враг у меня на прицеле!',12,0,100,11,0,67212,117390,0,'Хеминг Эрнестуэй'),
